/* Super SAT — Math question bank. Original content, extracted verbatim from Super SAT.html. */
const MM=[{"dom":"A","diff":1,"tpl":"A1","p":"If 6x + 11 = 17, what is the value of x?","e":"17 − (11) = 6, so 6x = 6, x = 1.","ans":[1.0],"disp":"1","id":1,"ty":"sp"},{"dom":"A","diff":1,"tpl":"A1","p":"If 3x − 2 = -11, what is the value of x?","e":"-11 − (-2) = -9, so 3x = -9, x = -3.","o":["-2","-3","-13/3","-5/3"],"a":1,"id":2,"ty":"mc"},{"dom":"A","diff":1,"tpl":"A1","p":"If 6x + 8 = 56, what is the value of x?","e":"56 − (8) = 48, so 6x = 48, x = 8.","o":["8","4/3","9","32/3"],"a":0,"id":3,"ty":"mc"},{"dom":"A","diff":1,"tpl":"A1","p":"If 7x + 9 = 93, what is the value of x?","e":"93 − (9) = 84, so 7x = 84, x = 12.","o":["30/7","102/7","12","13"],"a":2,"id":4,"ty":"mc"},{"dom":"A","diff":1,"tpl":"A2","p":"If 5x + 7 = 12, what is the value of 15x + 21?","e":"Ikkala tomonni 3 ga ko'paytiring: 15x + 21 = 3·12 = 36. x ni topish shart emas.","o":["36","29","43","12"],"a":0,"id":5,"ty":"mc"},{"dom":"A","diff":1,"tpl":"A2","p":"If 4x + 9 = 41, what is the value of 8x + 18?","e":"Ikkala tomonni 2 ga ko'paytiring: 8x + 18 = 2·41 = 82. x ni topish shart emas.","ans":[82.0],"disp":"82","id":6,"ty":"sp"},{"dom":"A","diff":1,"tpl":"A2","p":"If 3x + 10 = 28, what is the value of 9x + 30?","e":"Ikkala tomonni 3 ga ko'paytiring: 9x + 30 = 3·28 = 84. x ni topish shart emas.","o":["84","74","94","28"],"a":0,"id":7,"ty":"mc"},{"dom":"A","diff":1,"tpl":"A2","p":"If 5x + 10 = 35, what is the value of 20x + 40?","e":"Ikkala tomonni 4 ga ko'paytiring: 20x + 40 = 4·35 = 140. x ni topish shart emas.","o":["130","35","150","140"],"a":3,"id":8,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A3","p":"x + y = 24\nx − y = 6\nIn the system of equations above, what is the value of x?","e":"Tenglamalarni qo'shsak: 2x = 24+6 = 30, demak x = 15.","o":["12","15","9","18"],"a":1,"id":9,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A3","p":"x + y = 4\nx − y = 2\nIn the system of equations above, what is the value of x?","e":"Tenglamalarni qo'shsak: 2x = 4+2 = 6, demak x = 3.","o":["2","1","6","3"],"a":3,"id":10,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A3","p":"x + y = 17\nx − y = 3\nIn the system of equations above, what is the value of x?","e":"Tenglamalarni qo'shsak: 2x = 17+3 = 20, demak x = 10.","o":["10","7","8.5","14"],"a":0,"id":11,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A3","p":"x + y = 5\nx − y = 3\nIn the system of equations above, what is the value of x?","e":"Tenglamalarni qo'shsak: 2x = 5+3 = 8, demak x = 4.","o":["2","2.5","1","4"],"a":3,"id":12,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A4","p":"The linear function f satisfies f(2) = 18 and f(6) = 38. What is the value of f(10)?","e":"Qiyalik: (38−18)/(6−2) = 5. f(10) = f(6) + 4·5 = 58.","o":["58","43","63","48"],"a":0,"id":13,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A4","p":"The linear function f satisfies f(2) = 16 and f(6) = 36. What is the value of f(10)?","e":"Qiyalik: (36−16)/(6−2) = 5. f(10) = f(6) + 4·5 = 56.","ans":[56.0],"disp":"56","id":14,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A4","p":"The linear function f satisfies f(2) = 22 and f(6) = 46. What is the value of f(10)?","e":"Qiyalik: (46−22)/(6−2) = 6. f(10) = f(6) + 4·6 = 70.","ans":[70.0],"disp":"70","id":15,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A4","p":"The linear function f satisfies f(2) = 11 and f(6) = 31. What is the value of f(10)?","e":"Qiyalik: (31−11)/(6−2) = 5. f(10) = f(6) + 4·5 = 51.","o":["41","51","36","56"],"a":1,"id":16,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A5","p":"A plumber charges a flat fee of $30 plus $25 for each hour of work. If the plumber's total charge for a job was $80, for how many hours did the plumber work?","e":"30 + 25h = 80 → 25h = 50 → h = 2.","ans":[2.0],"disp":"2","id":17,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A5","p":"A plumber charges a flat fee of $30 plus $35 for each hour of work. If the plumber's total charge for a job was $310, for how many hours did the plumber work?","e":"30 + 35h = 310 → 35h = 280 → h = 8.","ans":[8.0],"disp":"8","id":18,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A5","p":"A plumber charges a flat fee of $25 plus $25 for each hour of work. If the plumber's total charge for a job was $125, for how many hours did the plumber work?","e":"25 + 25h = 125 → 25h = 100 → h = 4.","o":["5","29","4","3"],"a":2,"id":19,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A5","p":"A plumber charges a flat fee of $60 plus $20 for each hour of work. If the plumber's total charge for a job was $100, for how many hours did the plumber work?","e":"60 + 20h = 100 → 20h = 40 → h = 2.","o":["5","3","1","2"],"a":3,"id":20,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A6","p":"What is the greatest integer n for which 7n − 6 ≤ 13?","e":"7n ≤ 19, n ≤ 19/7 ≈ 2.71. Eng katta butun son: 2.","o":["2","1","19/7","3"],"a":0,"id":21,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A6","p":"What is the greatest integer n for which 5n − 7 ≤ 39?","e":"5n ≤ 46, n ≤ 9.2 ≈ 9.20. Eng katta butun son: 9.","ans":[9.0],"disp":"9","id":22,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A6","p":"What is the greatest integer n for which 4n − 1 ≤ 20?","e":"4n ≤ 21, n ≤ 5.25 ≈ 5.25. Eng katta butun son: 5.","o":["5.25","6","4","5"],"a":3,"id":23,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A6","p":"What is the greatest integer n for which 4n − 9 ≤ 21?","e":"4n ≤ 30, n ≤ 7.5 ≈ 7.50. Eng katta butun son: 7.","ans":[7.0],"disp":"7","id":24,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A10","p":"A line in the xy-plane passes through the points (-1, 2) and (3, 14). What is the y-intercept of the line?","e":"Qiyalik m = (14−(2))/(3−(-1)) = 3. y = 3x + b; (-1,2) dan b = 2 − 3·(-1) = 5.","o":["-5","5","3","2"],"a":1,"id":25,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A10","p":"A line in the xy-plane passes through the points (1, 0) and (5, 16). What is the y-intercept of the line?","e":"Qiyalik m = (16−(0))/(5−(1)) = 4. y = 4x + b; (1,0) dan b = 0 − 4·(1) = -4.","o":["0","-4","4","-3"],"a":1,"id":26,"ty":"mc"},{"dom":"A","diff":2,"tpl":"A10","p":"A line in the xy-plane passes through the points (-1, 9) and (3, -3). What is the y-intercept of the line?","e":"Qiyalik m = (-3−(9))/(3−(-1)) = -3. y = -3x + b; (-1,9) dan b = 9 − -3·(-1) = 6.","ans":[6.0],"disp":"6","id":27,"ty":"sp"},{"dom":"A","diff":2,"tpl":"A10","p":"A line in the xy-plane passes through the points (0, -5) and (3, 4). What is the y-intercept of the line?","e":"Qiyalik m = (4−(-5))/(3−(0)) = 3. y = 3x + b; (0,-5) dan b = -5 − 3·(0) = -5.","o":["5","-5","-2","3"],"a":1,"id":28,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A7","p":"2x + 4y = 5\nkx + 8y = 12\nIn the system of equations above, k is a constant. If the system has no solution, what is the value of k?","e":"Yechim bo'lmasligi uchun to'g'ri chiziqlar parallel (qiyaliklar teng), lekin ustma-ust tushmasligi kerak. Ikkinchi tenglamada y oldidagi koeffitsiyent 2 marta katta, demak k = 2·2 = 4.","o":["6","2","4","1"],"a":2,"id":29,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A7","p":"3x + 2y = 5\nkx + 4y = 14\nIn the system of equations above, k is a constant. If the system has no solution, what is the value of k?","e":"Yechim bo'lmasligi uchun to'g'ri chiziqlar parallel (qiyaliklar teng), lekin ustma-ust tushmasligi kerak. Ikkinchi tenglamada y oldidagi koeffitsiyent 2 marta katta, demak k = 2·3 = 6.","ans":[6.0],"disp":"6","id":30,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A7","p":"2x + 2y = 8\nkx + 6y = 26\nIn the system of equations above, k is a constant. If the system has no solution, what is the value of k?","e":"Yechim bo'lmasligi uchun to'g'ri chiziqlar parallel (qiyaliklar teng), lekin ustma-ust tushmasligi kerak. Ikkinchi tenglamada y oldidagi koeffitsiyent 3 marta katta, demak k = 3·2 = 6.","o":["6","3","2","8"],"a":0,"id":31,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A7","p":"5x + 4y = 6\nkx + 8y = 14\nIn the system of equations above, k is a constant. If the system has no solution, what is the value of k?","e":"Yechim bo'lmasligi uchun to'g'ri chiziqlar parallel (qiyaliklar teng), lekin ustma-ust tushmasligi kerak. Ikkinchi tenglamada y oldidagi koeffitsiyent 2 marta katta, demak k = 2·5 = 10.","o":["15","5","10","2"],"a":2,"id":32,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A8","p":"3x + 2y = 4\n15x + 10y = k\nIn the system of equations above, k is a constant. If the system has infinitely many solutions, what is the value of k?","e":"Cheksiz ko'p yechim uchun ikkinchi tenglama birinchisining 5 marta ko'paytirilgani bo'lishi kerak: k = 5·4 = 20.","ans":[20.0],"disp":"20","id":33,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A8","p":"6x + 3y = 4\n18x + 9y = k\nIn the system of equations above, k is a constant. If the system has infinitely many solutions, what is the value of k?","e":"Cheksiz ko'p yechim uchun ikkinchi tenglama birinchisining 3 marta ko'paytirilgani bo'lishi kerak: k = 3·4 = 12.","ans":[12.0],"disp":"12","id":34,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A8","p":"4x + 2y = 9\n16x + 8y = k\nIn the system of equations above, k is a constant. If the system has infinitely many solutions, what is the value of k?","e":"Cheksiz ko'p yechim uchun ikkinchi tenglama birinchisining 4 marta ko'paytirilgani bo'lishi kerak: k = 4·9 = 36.","o":["36","9","4","16"],"a":0,"id":35,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A8","p":"4x + 7y = 7\n16x + 28y = k\nIn the system of equations above, k is a constant. If the system has infinitely many solutions, what is the value of k?","e":"Cheksiz ko'p yechim uchun ikkinchi tenglama birinchisining 4 marta ko'paytirilgani bo'lishi kerak: k = 4·7 = 28.","ans":[28.0],"disp":"28","id":36,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A9","p":"A theater sold 80 tickets for a performance. Adult tickets cost $18 each and child tickets cost $6 each. The total revenue from ticket sales was $1068. How many adult tickets were sold?","e":"Adult = x, child = 80−x: 18x + 6(80−x) = 1068 → 12x = 588 → x = 49.","ans":[49.0],"disp":"49","id":37,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A9","p":"A theater sold 80 tickets for a performance. Adult tickets cost $18 each and child tickets cost $8 each. The total revenue from ticket sales was $1320. How many adult tickets were sold?","e":"Adult = x, child = 80−x: 18x + 8(80−x) = 1320 → 10x = 680 → x = 68.","ans":[68.0],"disp":"68","id":38,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A9","p":"A theater sold 50 tickets for a performance. Adult tickets cost $15 each and child tickets cost $10 each. The total revenue from ticket sales was $545. How many adult tickets were sold?","e":"Adult = x, child = 50−x: 15x + 10(50−x) = 545 → 5x = 45 → x = 9.","o":["109/3","41","9","14"],"a":2,"id":39,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A9","p":"A theater sold 60 tickets for a performance. Adult tickets cost $20 each and child tickets cost $10 each. The total revenue from ticket sales was $1010. How many adult tickets were sold?","e":"Adult = x, child = 60−x: 20x + 10(60−x) = 1010 → 10x = 410 → x = 41.","o":["41","50.5","46","19"],"a":0,"id":40,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A11","p":"Line ℓ is perpendicular to the line y = 4x − 2 and passes through the point (12, 6). What is the y-intercept of line ℓ?","e":"Perpendikulyar qiyalik: −1/4 = -0.25. y − (6) = -0.25(x − (12)); x=0 da y = 6 + 3 = 9.","ans":[9.0],"disp":"9","id":41,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A11","p":"Line ℓ is perpendicular to the line y = 2x + 4 and passes through the point (4, 3). What is the y-intercept of line ℓ?","e":"Perpendikulyar qiyalik: −1/2 = -0.5. y − (3) = -0.5(x − (4)); x=0 da y = 3 + 2 = 5.","ans":[5.0],"disp":"5","id":42,"ty":"sp"},{"dom":"A","diff":3,"tpl":"A11","p":"Line ℓ is perpendicular to the line y = 2x − 5 and passes through the point (2, 1). What is the y-intercept of line ℓ?","e":"Perpendikulyar qiyalik: −1/2 = -0.5. y − (1) = -0.5(x − (2)); x=0 da y = 1 + 1 = 2.","o":["2","1","0","-5"],"a":0,"id":43,"ty":"mc"},{"dom":"A","diff":3,"tpl":"A11","p":"Line ℓ is perpendicular to the line y = 3x − 4 and passes through the point (-3, 2). What is the y-intercept of line ℓ?","e":"Perpendikulyar qiyalik: −1/3 = -1/3. y − (2) = -1/3(x − (-3)); x=0 da y = 2 + -1 = 1.","o":["-4","1","2","3"],"a":1,"id":44,"ty":"mc"},{"dom":"V","diff":1,"tpl":"V1","p":"The function f is defined by f(x) = x² + 2x. What is the value of f(3)?","e":"f(3) = 1·(3)² + (2)·(3) + (0) = 15.","o":["9","18","15","-15"],"a":2,"id":45,"ty":"mc"},{"dom":"V","diff":1,"tpl":"V1","p":"The function f is defined by f(x) = x² + 4x − 8. What is the value of f(4)?","e":"f(4) = 1·(4)² + (4)·(4) + (-8) = 24.","ans":[24.0],"disp":"24","id":46,"ty":"sp"},{"dom":"V","diff":1,"tpl":"V1","p":"The function f is defined by f(x) = 2x² − 3x − 1. What is the value of f(0)?","e":"f(0) = 2·(0)² + (-3)·(0) + (-1) = -1.","ans":[-1.0],"disp":"-1","id":47,"ty":"sp"},{"dom":"V","diff":1,"tpl":"V1","p":"The function f is defined by f(x) = x² + 3x − 4. What is the value of f(-2)?","e":"f(-2) = 1·(-2)² + (3)·(-2) + (-4) = -6.","ans":[-6.0],"disp":"-6","id":48,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V2","p":"What is the positive solution to the equation x² − 4x − 21 = 0?","e":"Ko'paytuvchilarga ajrating: (x − 7)(x + 3) = 0, ildizlar 7 va -3. Musbat yechim: 7.","o":["4","-7","-3","7"],"a":3,"id":49,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V2","p":"What is the positive solution to the equation x² − x − 6 = 0?","e":"Ko'paytuvchilarga ajrating: (x − 3)(x + 2) = 0, ildizlar 3 va -2. Musbat yechim: 3.","o":["-3","1","3","-2"],"a":2,"id":50,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V2","p":"What is the positive solution to the equation x² − 5x − 6 = 0?","e":"Ko'paytuvchilarga ajrating: (x − 6)(x + 1) = 0, ildizlar 6 va -1. Musbat yechim: 6.","o":["-1","-6","6","5"],"a":2,"id":51,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V2","p":"What is the positive solution to the equation x² + 2x − 15 = 0?","e":"Ko'paytuvchilarga ajrating: (x − 3)(x + 5) = 0, ildizlar 3 va -5. Musbat yechim: 3.","ans":[3.0],"disp":"3","id":52,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V3","p":"The number of bacteria in a culture doubles every 2 hours. At the start of an experiment there are 100 bacteria. How many bacteria are in the culture 8 hours after the start?","e":"8 soat = 4 ta davr. 100·2^4 = 1600.","o":["25600","116","800","1600"],"a":3,"id":53,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V3","p":"The number of bacteria in a culture triples every 3 hours. At the start of an experiment there are 50 bacteria. How many bacteria are in the culture 12 hours after the start?","e":"12 soat = 4 ta davr. 50·3^4 = 4050.","o":["4050","1800","26572050","600"],"a":0,"id":54,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V3","p":"The number of bacteria in a culture doubles every 3 hours. At the start of an experiment there are 100 bacteria. How many bacteria are in the culture 12 hours after the start?","e":"12 soat = 4 ta davr. 100·2^4 = 1600.","ans":[1600.0],"disp":"1600","id":55,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V3","p":"The number of bacteria in a culture triples every 2 hours. At the start of an experiment there are 50 bacteria. How many bacteria are in the culture 4 hours after the start?","e":"4 soat = 2 ta davr. 50·3^2 = 450.","ans":[450.0],"disp":"450","id":56,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V4","p":"What is the minimum value of the function f(x) = x² − 8x + 35?","e":"To'liq kvadrat: x² − 8x + 35 = (x − 4)² + 19. Minimum qiymat 19.","o":["19","4","31","35"],"a":0,"id":57,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V4","p":"What is the minimum value of the function f(x) = x² − 8x + 18?","e":"To'liq kvadrat: x² − 8x + 18 = (x − 4)² + 2. Minimum qiymat 2.","o":["18","14","2","4"],"a":2,"id":58,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V4","p":"What is the minimum value of the function f(x) = x² − 6x + 10?","e":"To'liq kvadrat: x² − 6x + 10 = (x − 3)² + 1. Minimum qiymat 1.","ans":[1.0],"disp":"1","id":59,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V4","p":"What is the minimum value of the function f(x) = x² − 14x + 56?","e":"To'liq kvadrat: x² − 14x + 56 = (x − 7)² + 7. Minimum qiymat 7.","o":["105","49","56","7"],"a":3,"id":60,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V6","p":"The expression (3x + 5)(x + 2) can be written in the form px² + qx + r, where p, q, and r are constants. What is the value of q?","e":"Qavslarni oching: x oldidagi had = 3·(2) + 5·1 = 11.","o":["11","6","13","5"],"a":0,"id":61,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V6","p":"The expression (4x + 5)(2x + 1) can be written in the form px² + qx + r, where p, q, and r are constants. What is the value of q?","e":"Qavslarni oching: x oldidagi had = 4·(1) + 5·2 = 14.","ans":[14.0],"disp":"14","id":62,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V6","p":"The expression (4x + 5)(x + 3) can be written in the form px² + qx + r, where p, q, and r are constants. What is the value of q?","e":"Qavslarni oching: x oldidagi had = 4·(3) + 5·1 = 17.","o":["12","19","17","5"],"a":2,"id":63,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V6","p":"The expression (4x + 5)(3x + 1) can be written in the form px² + qx + r, where p, q, and r are constants. What is the value of q?","e":"Qavslarni oching: x oldidagi had = 4·(1) + 5·3 = 19.","o":["15","19","4","17"],"a":1,"id":64,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V7","p":"If 9ˣ = 3¹², what is the value of x?","e":"9 = 3^2, demak (3^2)^x = 3^2x = 3^12, kx = 12, x = 6.","o":["6","12","24","10"],"a":0,"id":65,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V7","p":"If 8ˣ = 2⁹, what is the value of x?","e":"8 = 2^3, demak (2^3)^x = 2^3x = 2^9, kx = 9, x = 3.","o":["3","9","27","6"],"a":0,"id":66,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V7","p":"If 125ˣ = 5¹⁵, what is the value of x?","e":"125 = 5^3, demak (5^3)^x = 5^3x = 5^15, kx = 15, x = 5.","o":["45","5","15","12"],"a":1,"id":67,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V7","p":"If 9ˣ = 3⁸, what is the value of x?","e":"9 = 3^2, demak (3^2)^x = 3^2x = 3^8, kx = 8, x = 4.","o":["6","8","16","4"],"a":3,"id":68,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V10","p":"What is the solution to the equation 12/(x − 4) = 6?","e":"x − 4 = 12/6 = 2 → x = 6.","ans":[6.0],"disp":"6","id":69,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V10","p":"What is the solution to the equation 16/(x − 2) = 4?","e":"x − 2 = 16/4 = 4 → x = 6.","o":["4","6","2","66"],"a":1,"id":70,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V10","p":"What is the solution to the equation 30/(x + 5) = 5?","e":"x + 5 = 30/5 = 6 → x = 1.","ans":[1.0],"disp":"1","id":71,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V10","p":"What is the solution to the equation 36/(x − 4) = 6?","e":"x − 4 = 36/6 = 6 → x = 10.","ans":[10.0],"disp":"10","id":72,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V13","p":"If f(x) = 5x − 4 and g(x) = x² + 5, what is the value of f(g(4))?","e":"g(4) = 4² + 5 = 21. f(21) = 5·21 + (-4) = 101.","o":["101","441","21","261"],"a":0,"id":73,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V13","p":"If f(x) = 2x + 2 and g(x) = x² + 5, what is the value of f(g(2))?","e":"g(2) = 2² + 5 = 9. f(9) = 2·9 + (2) = 20.","o":["20","81","11","41"],"a":0,"id":74,"ty":"mc"},{"dom":"V","diff":2,"tpl":"V13","p":"If f(x) = 2x − 4 and g(x) = x² + 3, what is the value of f(g(3))?","e":"g(3) = 3² + 3 = 12. f(12) = 2·12 + (-4) = 20.","ans":[20.0],"disp":"20","id":75,"ty":"sp"},{"dom":"V","diff":2,"tpl":"V13","p":"If f(x) = 5x + 5 and g(x) = x² + 1, what is the value of f(g(2))?","e":"g(2) = 2² + 1 = 5. f(5) = 5·5 + (5) = 30.","o":["30","226","25","16"],"a":0,"id":76,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V5","p":"x² + 12x + c = 0\nIn the equation above, c is a positive constant. If the equation has exactly one real solution, what is the value of c?","e":"Bitta haqiqiy yechim ⇒ diskriminant 0: 12² − 4c = 0 → c = 144/4 = 36.","ans":[36.0],"disp":"36","id":77,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V5","p":"x² + 8x + c = 0\nIn the equation above, c is a positive constant. If the equation has exactly one real solution, what is the value of c?","e":"Bitta haqiqiy yechim ⇒ diskriminant 0: 8² − 4c = 0 → c = 64/4 = 16.","ans":[16.0],"disp":"16","id":78,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V5","p":"x² + 14x + c = 0\nIn the equation above, c is a positive constant. If the equation has exactly one real solution, what is the value of c?","e":"Bitta haqiqiy yechim ⇒ diskriminant 0: 14² − 4c = 0 → c = 196/4 = 49.","o":["196","49","7","14"],"a":1,"id":79,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V5","p":"x² + 16x + c = 0\nIn the equation above, c is a positive constant. If the equation has exactly one real solution, what is the value of c?","e":"Bitta haqiqiy yechim ⇒ diskriminant 0: 16² − 4c = 0 → c = 256/4 = 64.","ans":[64.0],"disp":"64","id":80,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V8","p":"What is the solution to the equation √(x − 1) = x − 3?","e":"Ikkala tomonni kvadratga oshiring: x − 1 = (x − 3)². Yechimlar: x = 5 va x = 2. x = 2 da o'ng tomon manfiy (-1) — begona ildiz. To'g'ri javob: 5.","ans":[5.0],"disp":"5","id":81,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V8","p":"What is the solution to the equation √(x + 9) = x − 3?","e":"Ikkala tomonni kvadratga oshiring: x + 9 = (x − 3)². Yechimlar: x = 7 va x = 0. x = 0 da o'ng tomon manfiy (-3) — begona ildiz. To'g'ri javob: 7.","o":["0","7","6","8"],"a":1,"id":82,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V8","p":"What is the solution to the equation √(x + 1) = x − 1?","e":"Ikkala tomonni kvadratga oshiring: x + 1 = (x − 1)². Yechimlar: x = 3 va x = 0. x = 0 da o'ng tomon manfiy (-1) — begona ildiz. To'g'ri javob: 3.","o":["3","4","2","0"],"a":0,"id":83,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V8","p":"What is the solution to the equation √(x + 3) = x − 3?","e":"Ikkala tomonni kvadratga oshiring: x + 3 = (x − 3)². Yechimlar: x = 6 va x = 1. x = 1 da o'ng tomon manfiy (-2) — begona ildiz. To'g'ri javob: 6.","o":["6","1","7","5"],"a":0,"id":84,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V9","p":"y = x² + 4x − 1\ny = 3\nIf (x₁, y₁) and (x₂, y₂) are the two solutions to the system of equations above, what is the value of x₁ + x₂?","e":"Tenglashtiring: x² + 4x − 1 = 3 → x² + 4x − 4 = 0. Ildizlar yig'indisi = −(x oldidagi koeffitsiyent) = −(4) = -4.","ans":[-4.0],"disp":"-4","id":85,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V9","p":"y = x² − 3x − 2\ny = −3x + 5\nIf (x₁, y₁) and (x₂, y₂) are the two solutions to the system of equations above, what is the value of x₁ + x₂?","e":"Tenglashtiring: x² − 3x − 2 = −3x + 5 → x² − 7 = 0. Ildizlar yig'indisi = −(x oldidagi koeffitsiyent) = −(0) = 0.","ans":[0.0],"disp":"0","id":86,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V9","p":"y = x² + 3x − 2\ny = x + 1\nIf (x₁, y₁) and (x₂, y₂) are the two solutions to the system of equations above, what is the value of x₁ + x₂?","e":"Tenglashtiring: x² + 3x − 2 = x + 1 → x² + 2x − 3 = 0. Ildizlar yig'indisi = −(x oldidagi koeffitsiyent) = −(2) = -2.","o":["-3","-2","2","4"],"a":1,"id":87,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V9","p":"y = x² + x − 7\ny = 5x + 1\nIf (x₁, y₁) and (x₂, y₂) are the two solutions to the system of equations above, what is the value of x₁ + x₂?","e":"Tenglashtiring: x² + x − 7 = 5x + 1 → x² − 4x − 8 = 0. Ildizlar yig'indisi = −(x oldidagi koeffitsiyent) = −(-4) = 4.","ans":[4.0],"disp":"4","id":88,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V11","p":"What is the remainder when x³ − x² + x − 6 is divided by x − 2?","e":"Qoldiq teoremasi: qoldiq = f(2) = 2³ − 1·2² + (1)·2 + (-6) = 0.","o":["2","0","-6","8"],"a":1,"id":89,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V11","p":"What is the remainder when x³ − 2x² + 3x + 1 is divided by x − 2?","e":"Qoldiq teoremasi: qoldiq = f(2) = 2³ − 2·2² + (3)·2 + (1) = 7.","ans":[7.0],"disp":"7","id":90,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V11","p":"What is the remainder when x³ − x² + 2x + 4 is divided by x − 2?","e":"Qoldiq teoremasi: qoldiq = f(2) = 2³ − 1·2² + (2)·2 + (4) = 12.","ans":[12.0],"disp":"12","id":91,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V11","p":"What is the remainder when x³ − 4x² − 5 is divided by x − 3?","e":"Qoldiq teoremasi: qoldiq = f(3) = 3³ − 4·3² + (0)·3 + (-5) = -14.","ans":[-14.0],"disp":"-14","id":92,"ty":"sp"},{"dom":"V","diff":3,"tpl":"V12","p":"A sample of a radioactive substance has a mass of 320 grams. The substance has a half-life of 3 days, so the mass of the sample is halved every 3 days. What is the mass, in grams, of the sample after 9 days?","e":"9 kun = 3 ta yarim yemirilish davri. Massa = 320·(1/2)^3 = 40 gramm.","o":["302","311","320/9","40"],"a":3,"id":93,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V12","p":"A sample of a radioactive substance has a mass of 640 grams. The substance has a half-life of 5 days, so the mass of the sample is halved every 5 days. What is the mass, in grams, of the sample after 15 days?","e":"15 kun = 3 ta yarim yemirilish davri. Massa = 640·(1/2)^3 = 80 gramm.","o":["80","625","610","128/3"],"a":0,"id":94,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V12","p":"A sample of a radioactive substance has a mass of 160 grams. The substance has a half-life of 6 days, so the mass of the sample is halved every 6 days. What is the mass, in grams, of the sample after 18 days?","e":"18 kun = 3 ta yarim yemirilish davri. Massa = 160·(1/2)^3 = 20 gramm.","o":["142","80/9","20","124"],"a":2,"id":95,"ty":"mc"},{"dom":"V","diff":3,"tpl":"V12","p":"A sample of a radioactive substance has a mass of 160 grams. The substance has a half-life of 5 days, so the mass of the sample is halved every 5 days. What is the mass, in grams, of the sample after 15 days?","e":"15 kun = 3 ta yarim yemirilish davri. Massa = 160·(1/2)^3 = 20 gramm.","o":["20","130","32/3","145"],"a":0,"id":96,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P2","p":"The mean of five numbers is 25. Four of the numbers are 27, 29, 31, 33. What is the fifth number?","e":"Yig'indi = 5·25 = 125. Beshinchi son = 125 − 120 = 5.","o":["5","30","25","20"],"a":0,"id":97,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P2","p":"The mean of five numbers is 14. Four of the numbers are 11, 11, 21, 9. What is the fifth number?","e":"Yig'indi = 5·14 = 70. Beshinchi son = 70 − 52 = 18.","ans":[18.0],"disp":"18","id":98,"ty":"sp"},{"dom":"P","diff":1,"tpl":"P2","p":"The mean of five numbers is 21. Four of the numbers are 15, 20, 23, 17. What is the fifth number?","e":"Yig'indi = 5·21 = 105. Beshinchi son = 105 − 75 = 30.","ans":[30.0],"disp":"30","id":99,"ty":"sp"},{"dom":"P","diff":1,"tpl":"P2","p":"The mean of five numbers is 15. Four of the numbers are 18, 22, 9, 11. What is the fifth number?","e":"Yig'indi = 5·15 = 75. Beshinchi son = 75 − 60 = 15.","o":["0","15","16","20"],"a":1,"id":100,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P3","p":"A car travels at a constant speed of 36 miles per hour. At this rate, how many minutes does it take the car to travel 90 miles?","e":"Vaqt = 90/36 soat = 2.5 soat = 150 daqiqa.","o":["150","160","54","2.5"],"a":0,"id":101,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P3","p":"A car travels at a constant speed of 40 miles per hour. At this rate, how many minutes does it take the car to travel 80 miles?","e":"Vaqt = 80/40 soat = 2 soat = 120 daqiqa.","ans":[120.0],"disp":"120","id":102,"ty":"sp"},{"dom":"P","diff":1,"tpl":"P3","p":"A car travels at a constant speed of 40 miles per hour. At this rate, how many minutes does it take the car to travel 60 miles?","e":"Vaqt = 60/40 soat = 1.5 soat = 90 daqiqa.","ans":[90.0],"disp":"90","id":103,"ty":"sp"},{"dom":"P","diff":1,"tpl":"P3","p":"A car travels at a constant speed of 40 miles per hour. At this rate, how many minutes does it take the car to travel 40 miles?","e":"Vaqt = 40/40 soat = 1 soat = 60 daqiqa.","o":["60","40","1","70"],"a":0,"id":104,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P8","p":"A recipe uses flour and sugar in the ratio 4 to 7. If the recipe uses 12 cups of flour, how many cups of sugar does it use?","e":"Nisbat 4:7. 12/4 = 3; shakar = 3·7 = 21.","o":["19","84","15","21"],"a":3,"id":105,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P8","p":"A recipe uses flour and sugar in the ratio 2 to 3. If the recipe uses 4 cups of flour, how many cups of sugar does it use?","e":"Nisbat 2:3. 4/2 = 2; shakar = 2·3 = 6.","o":["12","7","6","5"],"a":2,"id":106,"ty":"mc"},{"dom":"P","diff":1,"tpl":"P8","p":"A recipe uses flour and sugar in the ratio 3 to 2. If the recipe uses 18 cups of flour, how many cups of sugar does it use?","e":"Nisbat 3:2. 18/3 = 6; shakar = 6·2 = 12.","ans":[12.0],"disp":"12","id":107,"ty":"sp"},{"dom":"P","diff":1,"tpl":"P8","p":"A recipe uses flour and sugar in the ratio 4 to 7. If the recipe uses 24 cups of flour, how many cups of sugar does it use?","e":"Nisbat 4:7. 24/4 = 6; shakar = 6·7 = 42.","ans":[42.0],"disp":"42","id":108,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P1","p":"A store reduced the price of a jacket by 10%. The sale price is $270. What was the original price, in dollars, of the jacket?","e":"Sotuv narxi = asl narxning 90%: 270 = 0.9·O → O = 300.","ans":[300.0],"disp":"300","id":109,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P1","p":"A store reduced the price of a jacket by 20%. The sale price is $96. What was the original price, in dollars, of the jacket?","e":"Sotuv narxi = asl narxning 80%: 96 = 0.8·O → O = 120.","ans":[120.0],"disp":"120","id":110,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P1","p":"A store reduced the price of a jacket by 50%. The sale price is $30. What was the original price, in dollars, of the jacket?","e":"Sotuv narxi = asl narxning 50%: 30 = 0.5·O → O = 60.","o":["61","80","45","60"],"a":3,"id":111,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P1","p":"A store reduced the price of a jacket by 30%. The sale price is $140. What was the original price, in dollars, of the jacket?","e":"Sotuv narxi = asl narxning 70%: 140 = 0.7·O → O = 200.","ans":[200.0],"disp":"200","id":112,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P4","p":"The data set 5, 10, 22, 23, 34 has a median of 22. A new value, 69, is added to the data set. What is the median of the new data set?","e":"Yangi to'plam: 5, 10, 22, 23, 34, 69 (6 ta son). Median = o'rtadagi ikki sonning o'rtachasi: (22 + 23)/2 = 22.5.","o":["23","22","24.5","22.5"],"a":3,"id":113,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P4","p":"The data set 5, 11, 23, 27, 33 has a median of 23. A new value, 68, is added to the data set. What is the median of the new data set?","e":"Yangi to'plam: 5, 11, 23, 27, 33, 68 (6 ta son). Median = o'rtadagi ikki sonning o'rtachasi: (23 + 27)/2 = 25.","ans":[25.0],"disp":"25","id":114,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P4","p":"The data set 8, 13, 14, 34, 37 has a median of 14. A new value, 57, is added to the data set. What is the median of the new data set?","e":"Yangi to'plam: 8, 13, 14, 34, 37, 57 (6 ta son). Median = o'rtadagi ikki sonning o'rtachasi: (14 + 34)/2 = 24.","o":["34","26","24","14"],"a":2,"id":115,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P4","p":"The data set 3, 12, 20, 31, 32 has a median of 20. A new value, 49, is added to the data set. What is the median of the new data set?","e":"Yangi to'plam: 3, 12, 20, 31, 32, 49 (6 ta son). Median = o'rtadagi ikki sonning o'rtachasi: (20 + 31)/2 = 25.5.","o":["25.5","27.5","31","20"],"a":0,"id":116,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P5","p":"A survey asked 125 students whether they prefer music or art. Among the juniors, 31 preferred music and 33 preferred art. Among the seniors, 16 preferred music and 45 preferred art. If one of the students who preferred art is chosen at random, what is the probability that the chosen student is a senior?","e":"Rasmni afzal ko'rganlar: 33+45 = 78. Ulardan seniorlar 45 ta. Ehtimollik = 45/78 = 15/26.","o":["9/25","45/61","11/26","15/26"],"a":3,"id":117,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P5","p":"A survey asked 107 students whether they prefer music or art. Among the juniors, 17 preferred music and 35 preferred art. Among the seniors, 24 preferred music and 31 preferred art. If one of the students who preferred art is chosen at random, what is the probability that the chosen student is a senior?","e":"Rasmni afzal ko'rganlar: 35+31 = 66. Ulardan seniorlar 31 ta. Ehtimollik = 31/66.","o":["31/55","35/66","31/107","31/66"],"a":3,"id":118,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P5","p":"A survey asked 120 students whether they prefer music or art. Among the juniors, 27 preferred music and 34 preferred art. Among the seniors, 39 preferred music and 20 preferred art. If one of the students who preferred art is chosen at random, what is the probability that the chosen student is a senior?","e":"Rasmni afzal ko'rganlar: 34+20 = 54. Ulardan seniorlar 20 ta. Ehtimollik = 20/54 = 10/27.","o":["1/6","17/27","20/59","10/27"],"a":3,"id":119,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P5","p":"A survey asked 107 students whether they prefer music or art. Among the juniors, 26 preferred music and 20 preferred art. Among the seniors, 28 preferred music and 33 preferred art. If one of the students who preferred art is chosen at random, what is the probability that the chosen student is a senior?","e":"Rasmni afzal ko'rganlar: 20+33 = 53. Ulardan seniorlar 33 ta. Ehtimollik = 33/53.","o":["33/61","33/53","20/53","33/107"],"a":1,"id":120,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P6","p":"The price of a share of stock increased by 30% in one month and then decreased by 10% the next month. The price of the share at the end of the second month is what percent of its price at the start of the first month?","e":"Koeffitsiyent: 13/10·9/10 = 1.17 → 117%.","ans":[117.0],"disp":"117","id":121,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P6","p":"The price of a share of stock increased by 50% in one month and then decreased by 40% the next month. The price of the share at the end of the second month is what percent of its price at the start of the first month?","e":"Koeffitsiyent: 3/2·3/5 = 0.9 → 90%.","o":["110","90","95","100"],"a":1,"id":122,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P6","p":"The price of a share of stock increased by 10% in one month and then decreased by 20% the next month. The price of the share at the end of the second month is what percent of its price at the start of the first month?","e":"Koeffitsiyent: 11/10·4/5 = 0.88 → 88%.","o":["93","100","90","88"],"a":3,"id":123,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P6","p":"The price of a share of stock increased by 25% in one month and then decreased by 20% the next month. The price of the share at the end of the second month is what percent of its price at the start of the first month?","e":"Koeffitsiyent: 5/4·4/5 = 1 → 100%.","ans":[100.0],"disp":"100","id":124,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P10","p":"A scientist modeled the water in a tank, in liters, y, at x minutes after filling began with the equation y = 5x + 20. Which of the following is the best interpretation of 5 in this context?","e":"y = 5x + 20 da 5 — qiyalik: x 1 birlikka oshganda y ning taxminiy o'sishi. 20 esa x = 0 dagi qiymat.","o":["The total predicted water in a tank after 5 units of x","The predicted increase in the water in a tank for each additional unit of x","The predicted water in a tank when x = 0","The predicted water in a tank when x = 5"],"a":1,"id":125,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P10","p":"A scientist modeled the distance a drone has traveled, in meters, y, at x seconds after launch with the equation y = 6x + 20. Which of the following is the best interpretation of 6 in this context?","e":"y = 6x + 20 da 6 — qiyalik: x 1 birlikka oshganda y ning taxminiy o'sishi. 20 esa x = 0 dagi qiymat.","o":["The total predicted distance a drone has traveled after 6 units of x","The predicted distance a drone has traveled when x = 6","The predicted increase in the distance a drone has traveled for each additional unit of x","The predicted distance a drone has traveled when x = 0"],"a":2,"id":126,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P10","p":"A scientist modeled the height of a sunflower, in centimeters, y, at x days after planting with the equation y = 4x + 12. Which of the following is the best interpretation of 4 in this context?","e":"y = 4x + 12 da 4 — qiyalik: x 1 birlikka oshganda y ning taxminiy o'sishi. 12 esa x = 0 dagi qiymat.","o":["The predicted increase in the height of a sunflower for each additional unit of x","The predicted height of a sunflower when x = 0","The predicted height of a sunflower when x = 4","The total predicted height of a sunflower after 4 units of x"],"a":0,"id":127,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P10","p":"A scientist modeled the height of a sunflower, in centimeters, y, at x days after planting with the equation y = 2x + 12. Which of the following is the best interpretation of 2 in this context?","e":"y = 2x + 12 da 2 — qiyalik: x 1 birlikka oshganda y ning taxminiy o'sishi. 12 esa x = 0 dagi qiymat.","o":["The predicted height of a sunflower when x = 2","The predicted increase in the height of a sunflower for each additional unit of x","The total predicted height of a sunflower after 2 units of x","The predicted height of a sunflower when x = 0"],"a":1,"id":128,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P11","p":"A city has 15,000 registered voters. In a random sample of 500 of these voters, 175 said they support a new park. Based on the sample, which is the best estimate of the number of the 15,000 registered voters who support the park?","e":"Ulush: 175/500. Taxmin: 15000·175/500 = 5250.","ans":[5250.0],"disp":"5250","id":129,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P11","p":"A city has 20,000 registered voters. In a random sample of 250 of these voters, 111 said they support a new park. Based on the sample, which is the best estimate of the number of the 20,000 registered voters who support the park?","e":"Ulush: 111/250. Taxmin: 20000·111/250 = 8880.","o":["8880","44.4","11120","22200"],"a":0,"id":130,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P11","p":"A city has 15,000 registered voters. In a random sample of 500 of these voters, 194 said they support a new park. Based on the sample, which is the best estimate of the number of the 15,000 registered voters who support the park?","e":"Ulush: 194/500. Taxmin: 15000·194/500 = 5820.","ans":[5820.0],"disp":"5820","id":131,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P11","p":"A city has 20,000 registered voters. In a random sample of 200 of these voters, 101 said they support a new park. Based on the sample, which is the best estimate of the number of the 20,000 registered voters who support the park?","e":"Ulush: 101/200. Taxmin: 20000·101/200 = 10100.","o":["50.5","9900","10100","20200"],"a":2,"id":132,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P12","p":"The mean of 8 numbers is 27. When one of the numbers, 34, is removed, what is the mean of the remaining 7 numbers?","e":"Yig'indi = 8·27 = 216. 34 olib tashlansa: 182. Yangi o'rtacha = 182/7 = 26.","o":["216/7","25","26","27"],"a":2,"id":133,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P12","p":"The mean of 5 numbers is 19. When one of the numbers, 23, is removed, what is the mean of the remaining 4 numbers?","e":"Yig'indi = 5·19 = 95. 23 olib tashlansa: 72. Yangi o'rtacha = 72/4 = 18.","ans":[18.0],"disp":"18","id":134,"ty":"sp"},{"dom":"P","diff":2,"tpl":"P12","p":"The mean of 5 numbers is 16. When one of the numbers, 32, is removed, what is the mean of the remaining 4 numbers?","e":"Yig'indi = 5·16 = 80. 32 olib tashlansa: 48. Yangi o'rtacha = 48/4 = 12.","o":["20","16","11","12"],"a":3,"id":135,"ty":"mc"},{"dom":"P","diff":2,"tpl":"P12","p":"The mean of 6 numbers is 23. When one of the numbers, 38, is removed, what is the mean of the remaining 5 numbers?","e":"Yig'indi = 6·23 = 138. 38 olib tashlansa: 100. Yangi o'rtacha = 100/5 = 20.","ans":[20.0],"disp":"20","id":136,"ty":"sp"},{"dom":"P","diff":3,"tpl":"P7","p":"Data set A: 14, 18, 22, 26, 30\nData set B: 18, 20, 22, 24, 26\nWhich of the following statements about the two data sets is true?","e":"Ikkala to'plamning o'rtachasi 22 va sonlari teng, lekin to'plam A qiymatlari o'rtachadan uzoqroq joylashgan, shuning uchun uning standart og'ishi katta.","o":["The standard deviation of data set A is greater, because its values are more spread out from the mean.","The data sets have the same standard deviation, because they have the same mean.","The standard deviation of data set B is greater, because its values are more spread out from the mean.","The data sets have the same standard deviation, because they have the same number of values."],"a":0,"id":137,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P7","p":"Data set A: 36, 38, 40, 42, 44\nData set B: 32, 36, 40, 44, 48\nWhich of the following statements about the two data sets is true?","e":"Ikkala to'plamning o'rtachasi 40 va sonlari teng, lekin to'plam B qiymatlari o'rtachadan uzoqroq joylashgan, shuning uchun uning standart og'ishi katta.","o":["The data sets have the same standard deviation, because they have the same mean.","The data sets have the same standard deviation, because they have the same number of values.","The standard deviation of data set A is greater, because its values are more spread out from the mean.","The standard deviation of data set B is greater, because its values are more spread out from the mean."],"a":3,"id":138,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P7","p":"Data set A: 22, 24, 26, 28, 30\nData set B: 18, 22, 26, 30, 34\nWhich of the following statements about the two data sets is true?","e":"Ikkala to'plamning o'rtachasi 26 va sonlari teng, lekin to'plam B qiymatlari o'rtachadan uzoqroq joylashgan, shuning uchun uning standart og'ishi katta.","o":["The data sets have the same standard deviation, because they have the same mean.","The data sets have the same standard deviation, because they have the same number of values.","The standard deviation of data set B is greater, because its values are more spread out from the mean.","The standard deviation of data set A is greater, because its values are more spread out from the mean."],"a":2,"id":139,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P7","p":"Data set A: 12, 16, 20, 24, 28\nData set B: 16, 18, 20, 22, 24\nWhich of the following statements about the two data sets is true?","e":"Ikkala to'plamning o'rtachasi 20 va sonlari teng, lekin to'plam A qiymatlari o'rtachadan uzoqroq joylashgan, shuning uchun uning standart og'ishi katta.","o":["The standard deviation of data set B is greater, because its values are more spread out from the mean.","The data sets have the same standard deviation, because they have the same number of values.","The data sets have the same standard deviation, because they have the same mean.","The standard deviation of data set A is greater, because its values are more spread out from the mean."],"a":3,"id":140,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P9","p":"In a study, 85 participants were randomly assigned to follow either Plan X or Plan Y. After eight weeks, 26 participants in Plan X improved and 31 did not improve. In Plan Y, 14 improved and 14 did not improve. If a participant who did NOT improve is selected at random, what is the probability that the participant was in Plan X?","e":"Yaxshilanmaganlar: 31+14 = 45. Ulardan X rejasida 31 ta. Ehtimollik = 31/45.","o":["26/57","31/85","31/45","31/57"],"a":2,"id":141,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P9","p":"In a study, 128 participants were randomly assigned to follow either Plan X or Plan Y. After eight weeks, 40 participants in Plan X improved and 35 did not improve. In Plan Y, 34 improved and 19 did not improve. If a participant who did NOT improve is selected at random, what is the probability that the participant was in Plan X?","e":"Yaxshilanmaganlar: 35+19 = 54. Ulardan X rejasida 35 ta. Ehtimollik = 35/54.","o":["35/54","8/15","35/128","7/15"],"a":0,"id":142,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P9","p":"In a study, 89 participants were randomly assigned to follow either Plan X or Plan Y. After eight weeks, 12 participants in Plan X improved and 23 did not improve. In Plan Y, 29 improved and 25 did not improve. If a participant who did NOT improve is selected at random, what is the probability that the participant was in Plan X?","e":"Yaxshilanmaganlar: 23+25 = 48. Ulardan X rejasida 23 ta. Ehtimollik = 23/48.","o":["12/35","23/89","23/48","23/35"],"a":2,"id":143,"ty":"mc"},{"dom":"P","diff":3,"tpl":"P9","p":"In a study, 62 participants were randomly assigned to follow either Plan X or Plan Y. After eight weeks, 19 participants in Plan X improved and 12 did not improve. In Plan Y, 11 improved and 20 did not improve. If a participant who did NOT improve is selected at random, what is the probability that the participant was in Plan X?","e":"Yaxshilanmaganlar: 12+20 = 32. Ulardan X rejasida 12 ta. Ehtimollik = 12/32 = 0.375.","o":["3/8","19/31","6/31","12/31"],"a":0,"id":144,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G1","p":"A rectangle has a perimeter of 24 centimeters and a length of 7 centimeters. What is the area, in square centimeters, of the rectangle?","e":"2(7+W) = 24 → W = 5. Yuza = 7·5 = 35.","o":["70","168","35","119"],"a":2,"id":145,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G1","p":"A rectangle has a perimeter of 22 centimeters and a length of 8 centimeters. What is the area, in square centimeters, of the rectangle?","e":"2(8+W) = 22 → W = 3. Yuza = 8·3 = 24.","o":["24","48","112","176"],"a":0,"id":146,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G1","p":"A rectangle has a perimeter of 20 centimeters and a length of 7 centimeters. What is the area, in square centimeters, of the rectangle?","e":"2(7+W) = 20 → W = 3. Yuza = 7·3 = 21.","ans":[21.0],"disp":"21","id":147,"ty":"sp"},{"dom":"G","diff":1,"tpl":"G1","p":"A rectangle has a perimeter of 42 centimeters and a length of 13 centimeters. What is the area, in square centimeters, of the rectangle?","e":"2(13+W) = 42 → W = 8. Yuza = 13·8 = 104.","o":["104","377","546","208"],"a":0,"id":148,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G2","p":"The measures of the three angles of a triangle are in the ratio 2:3:4. What is the measure, in degrees, of the largest angle?","e":"2+3+4 = 9 qism = 180°, 1 qism = 20°. Eng katta burchak = 4·20 = 80°.","o":["80","20","100","60"],"a":0,"id":149,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G2","p":"The measures of the three angles of a triangle are in the ratio 2:3:5. What is the measure, in degrees, of the largest angle?","e":"2+3+5 = 10 qism = 180°, 1 qism = 18°. Eng katta burchak = 5·18 = 90°.","o":["90","91","72","18"],"a":0,"id":150,"ty":"mc"},{"dom":"G","diff":1,"tpl":"G2","p":"The measures of the three angles of a triangle are in the ratio 1:3:5. What is the measure, in degrees, of the largest angle?","e":"1+3+5 = 9 qism = 180°, 1 qism = 20°. Eng katta burchak = 5·20 = 100°.","ans":[100.0],"disp":"100","id":151,"ty":"sp"},{"dom":"G","diff":1,"tpl":"G2","p":"The measures of the three angles of a triangle are in the ratio 1:4:5. What is the measure, in degrees, of the largest angle?","e":"1+4+5 = 10 qism = 180°, 1 qism = 18°. Eng katta burchak = 5·18 = 90°.","o":["72","18","90","91"],"a":2,"id":152,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G3","p":"A ladder 25 feet long leans against a vertical wall. The base of the ladder is 7 feet from the wall. How high up the wall, in feet, does the ladder reach?","e":"Pifagor: h² = 25² − 7² = 576, h = 24.","o":["576","18","32","24"],"a":3,"id":153,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G3","p":"A ladder 17 feet long leans against a vertical wall. The base of the ladder is 8 feet from the wall. How high up the wall, in feet, does the ladder reach?","e":"Pifagor: h² = 17² − 8² = 225, h = 15.","o":["25","225","15","9"],"a":2,"id":154,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G3","p":"A ladder 20 feet long leans against a vertical wall. The base of the ladder is 12 feet from the wall. How high up the wall, in feet, does the ladder reach?","e":"Pifagor: h² = 20² − 12² = 256, h = 16.","o":["16","8","256","32"],"a":0,"id":155,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G3","p":"A ladder 26 feet long leans against a vertical wall. The base of the ladder is 10 feet from the wall. How high up the wall, in feet, does the ladder reach?","e":"Pifagor: h² = 26² − 10² = 576, h = 24.","ans":[24.0],"disp":"24","id":156,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G4","p":"A circle has a circumference of 20π. The area of the circle is kπ. What is the value of k?","e":"2πr = 20π → r = 10. Yuza = πr² = 100π, k = 100.","o":["10","400","100","20"],"a":2,"id":157,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G4","p":"A circle has a circumference of 18π. The area of the circle is kπ. What is the value of k?","e":"2πr = 18π → r = 9. Yuza = πr² = 81π, k = 81.","o":["9","81","324","18"],"a":1,"id":158,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G4","p":"A circle has a circumference of 12π. The area of the circle is kπ. What is the value of k?","e":"2πr = 12π → r = 6. Yuza = πr² = 36π, k = 36.","o":["36","12","6","144"],"a":0,"id":159,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G4","p":"A circle has a circumference of 6π. The area of the circle is kπ. What is the value of k?","e":"2πr = 6π → r = 3. Yuza = πr² = 9π, k = 9.","ans":[9.0],"disp":"9","id":160,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G5","p":"Triangle ABC is similar to triangle DEF, where A corresponds to D, B to E, and C to F. AB = 4, BC = 9, and DE = 12. What is the length of EF?","e":"O'xshashlik koeffitsiyenti = DE/AB = 3. EF = 3·9 = 27.","o":["17","21","12","27"],"a":3,"id":161,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G5","p":"Triangle ABC is similar to triangle DEF, where A corresponds to D, B to E, and C to F. AB = 4, BC = 9, and DE = 8. What is the length of EF?","e":"O'xshashlik koeffitsiyenti = DE/AB = 2. EF = 2·9 = 18.","o":["17","13","11","18"],"a":3,"id":162,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G5","p":"Triangle ABC is similar to triangle DEF, where A corresponds to D, B to E, and C to F. AB = 6, BC = 8, and DE = 12. What is the length of EF?","e":"O'xshashlik koeffitsiyenti = DE/AB = 2. EF = 2·8 = 16.","o":["20","10","14","16"],"a":3,"id":163,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G5","p":"Triangle ABC is similar to triangle DEF, where A corresponds to D, B to E, and C to F. AB = 4, BC = 4, and DE = 8. What is the length of EF?","e":"O'xshashlik koeffitsiyenti = DE/AB = 2. EF = 2·4 = 8.","ans":[8.0],"disp":"8","id":164,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G8","p":"A right circular cylinder has a volume of 64π cubic inches and a base radius of 4 inches. What is the height, in inches, of the cylinder?","e":"V = πr²h → 64π = π·16·h → h = 4.","ans":[4.0],"disp":"4","id":165,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G8","p":"A right circular cylinder has a volume of 28π cubic inches and a base radius of 2 inches. What is the height, in inches, of the cylinder?","e":"V = πr²h → 28π = π·4·h → h = 7.","ans":[7.0],"disp":"7","id":166,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G8","p":"A right circular cylinder has a volume of 200π cubic inches and a base radius of 5 inches. What is the height, in inches, of the cylinder?","e":"V = πr²h → 200π = π·25·h → h = 8.","ans":[8.0],"disp":"8","id":167,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G8","p":"A right circular cylinder has a volume of 112π cubic inches and a base radius of 4 inches. What is the height, in inches, of the cylinder?","e":"V = πr²h → 112π = π·16·h → h = 7.","o":["14","7","11","28"],"a":1,"id":168,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G10","p":"In a right triangle, the two acute angles measure 30° and 60°. The shorter leg has length 6. What is the length of the longer leg?","e":"30-60-90 uchburchakda tomonlar nisbati 1 : √3 : 2. Uzun katet = 6√3.","o":["12","6√3","7","6√2"],"a":1,"id":169,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G10","p":"In a right triangle, the two acute angles measure 30° and 60°. The shorter leg has length 2. What is the length of the longer leg?","e":"30-60-90 uchburchakda tomonlar nisbati 1 : √3 : 2. Uzun katet = 2√3.","o":["2√3","2√2","3","4"],"a":0,"id":170,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G10","p":"In a right triangle, the two acute angles measure 30° and 60°. The shorter leg has length 4. What is the length of the longer leg?","e":"30-60-90 uchburchakda tomonlar nisbati 1 : √3 : 2. Uzun katet = 4√3.","o":["5","4√2","4√3","8"],"a":2,"id":171,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G10","p":"In a right triangle, the two acute angles measure 30° and 60°. The shorter leg has length 3. What is the length of the longer leg?","e":"30-60-90 uchburchakda tomonlar nisbati 1 : √3 : 2. Uzun katet = 3√3.","o":["4","6","3√3","3√2"],"a":2,"id":172,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G11","p":"The endpoints of a diameter of a circle in the xy-plane are (0, -4) and (10, 0). What are the coordinates of the center of the circle?","e":"Markaz — diametr uchlarining o'rta nuqtasi: ((0+10)/2, (-4+0)/2) = (5, -2).","o":["(5, -1)","(5, 2)","(5, -2)","(10, 4)"],"a":2,"id":173,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G11","p":"The endpoints of a diameter of a circle in the xy-plane are (-3, 2) and (1, 10). What are the coordinates of the center of the circle?","e":"Markaz — diametr uchlarining o'rta nuqtasi: ((-3+1)/2, (2+10)/2) = (-1, 6).","o":["(4, 8)","(2, 4)","(-1, 7)","(-1, 6)"],"a":3,"id":174,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G11","p":"The endpoints of a diameter of a circle in the xy-plane are (-2, 1) and (6, 9). What are the coordinates of the center of the circle?","e":"Markaz — diametr uchlarining o'rta nuqtasi: ((-2+6)/2, (1+9)/2) = (2, 5).","o":["(4, 4)","(8, 8)","(2, 5)","(2, 6)"],"a":2,"id":175,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G11","p":"The endpoints of a diameter of a circle in the xy-plane are (-5, 0) and (5, 2). What are the coordinates of the center of the circle?","e":"Markaz — diametr uchlarining o'rta nuqtasi: ((-5+5)/2, (0+2)/2) = (0, 1).","o":["(5, 1)","(10, 2)","(0, 2)","(0, 1)"],"a":3,"id":176,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G12","p":"In the xy-plane, point P has coordinates (1, 1) and point Q has coordinates (4, 5). What is the distance between P and Q?","e":"d = √((3)² + (4)²) = √25 = 5.","o":["5","6","25","7"],"a":0,"id":177,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G12","p":"In the xy-plane, point P has coordinates (-3, -3) and point Q has coordinates (6, 9). What is the distance between P and Q?","e":"d = √((9)² + (12)²) = √225 = 15.","ans":[15.0],"disp":"15","id":178,"ty":"sp"},{"dom":"G","diff":2,"tpl":"G12","p":"In the xy-plane, point P has coordinates (1, -1) and point Q has coordinates (7, 7). What is the distance between P and Q?","e":"d = √((6)² + (8)²) = √100 = 10.","o":["11","100","10","14"],"a":2,"id":179,"ty":"mc"},{"dom":"G","diff":2,"tpl":"G12","p":"In the xy-plane, point P has coordinates (-3, 0) and point Q has coordinates (6, 12). What is the distance between P and Q?","e":"d = √((9)² + (12)²) = √225 = 15.","o":["21","225","16","15"],"a":3,"id":180,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G6","p":"In right triangle ABC, the measure of angle B is 90°, AB = 8, and BC = 15. What is the value of tan(A)?","e":"tan A = qarshi katet / yonidagi katet = BC/AB = 15/8.","o":["8/15","15/8","8/17","15/17"],"a":1,"id":181,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G6","p":"In right triangle ABC, the measure of angle B is 90° and sin(A) = 8/17. What is the value of cos(C)?","e":"A va C o'tkir burchaklar bir-birini 90° ga to'ldiradi, shuning uchun cos(C) = sin(A) = 8/17.","o":["17/8","8/17","15/17","8/15"],"a":1,"id":182,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G6","p":"In right triangle ABC, the measure of angle B is 90°, AB = 7, and BC = 24. What is the value of tan(A)?","e":"tan A = qarshi katet / yonidagi katet = BC/AB = 24/7.","o":["7/25","7/24","24/7","24/25"],"a":2,"id":183,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G6","p":"In right triangle ABC, the measure of angle B is 90° and sin(A) = 7/25. What is the value of cos(C)?","e":"A va C o'tkir burchaklar bir-birini 90° ga to'ldiradi, shuning uchun cos(C) = sin(A) = 7/25.","o":["25/7","24/25","7/25","7/24"],"a":2,"id":184,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G7","p":"The equation x² + y² − 10x − 10y = 14 defines a circle in the xy-plane. What is the radius of the circle?","e":"To'liq kvadrat: (x − 5)² + (y − 5)² = 14 + 25 + 25 = 64. Radius = 8.","ans":[8.0],"disp":"8","id":185,"ty":"sp"},{"dom":"G","diff":3,"tpl":"G7","p":"The equation x² + y² − 10x − 8y = -32 defines a circle in the xy-plane. What is the radius of the circle?","e":"To'liq kvadrat: (x − 5)² + (y − 4)² = -32 + 25 + 16 = 9. Radius = 3.","o":["1.5","9","3","-32"],"a":2,"id":186,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G7","p":"The equation x² + y² − 2x − 4y = 59 defines a circle in the xy-plane. What is the radius of the circle?","e":"To'liq kvadrat: (x − 1)² + (y − 2)² = 59 + 1 + 4 = 64. Radius = 8.","ans":[8.0],"disp":"8","id":187,"ty":"sp"},{"dom":"G","diff":3,"tpl":"G7","p":"The equation x² + y² − 6x − 8y = -16 defines a circle in the xy-plane. What is the radius of the circle?","e":"To'liq kvadrat: (x − 3)² + (y − 4)² = -16 + 9 + 16 = 9. Radius = 3.","ans":[3.0],"disp":"3","id":188,"ty":"sp"},{"dom":"G","diff":3,"tpl":"G9","p":"A sector of a circle has a central angle of 90° and a radius of 6 centimeters. The area of the sector is kπ square centimeters. What is the value of k?","e":"Sektor yuzi = (90/360)·π·6² = 9π, k = 9.","o":["9","36","3","1.5"],"a":0,"id":189,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G9","p":"A sector of a circle has a central angle of 90° and a radius of 10 centimeters. The area of the sector is kπ square centimeters. What is the value of k?","e":"Sektor yuzi = (90/360)·π·10² = 25π, k = 25.","o":["25","2.5","5","100"],"a":0,"id":190,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G9","p":"A sector of a circle has a central angle of 120° and a radius of 12 centimeters. The area of the sector is kπ square centimeters. What is the value of k?","e":"Sektor yuzi = (120/360)·π·12² = 48π, k = 48.","o":["4","48","8","144"],"a":1,"id":191,"ty":"mc"},{"dom":"G","diff":3,"tpl":"G9","p":"A sector of a circle has a central angle of 90° and a radius of 8 centimeters. The area of the sector is kπ square centimeters. What is the value of k?","e":"Sektor yuzi = (90/360)·π·8² = 16π, k = 16.","o":["4","16","64","2"],"a":1,"id":192,"ty":"mc"}];
